    internal static IEnumerable<(string Name,Action Run)> All() {
        yield return("rc5 production trust rejects test-signed fixtures and unsafe helper context",NoProductionTrust);
        yield return("rc5 synthetic RSA-PSS signed manifest authenticates exact package metadata",Signature);
        yield return("rc5 wrong signature key canonical encoding and duplicate JSON are rejected",BadSignatures);
        yield return("rc5 signed repository platform channel version and downgrade are enforced",VersionBindings);
        yield return("rc5 signed asset filename size digest and member hashes are enforced",HashBindings);
        yield return("rc5 signed ZIP inventory refuses unexpected executables traversal and absolute paths",UnsafeZip);
        yield return("rc5 ZIP Unix symlinks Windows reparse entries and duplicate paths are rejected",ArchiveLinks);
        yield return("rc5 signed ZIP rejects excess extraction size missing entries and corrupt data",ZipLimits);
        yield return("rc5 verified staging stays outside install directory and preserves user files",Stage);
        yield return("rc5 staging inside application directory is refused before creating storage",StagingPreflight);
        yield return("rc5 replacement verifies installed bytes and invokes restart only after commit",Apply);
        yield return("rc5 failed replacement rolls back exact original without launching candidate",Rollback);
        yield return("rc5 failed restart restores original and keeps recovery evidence",RestartFailure);
        yield return("rc5 fallback restart accepts only verified unchanged previous executable",PreviousRestart);
        yield return("rc5 changed installed payload backup and target fail closed",ChangedFiles);
        yield return("rc5 rollback never overwrites external post-install changes",ExternalChange);
        yield return("rc5 actual Windows file sharing lock preserves existing installation",LockedTarget);
        yield return("rc5 injected denied access and write failure preserve old EXE",WriteFailure);
        yield return("rc5 real read-only executable refuses replacement without clearing attributes",ReadOnlyTarget);
        yield return("rc5 missing destination is recovered from verified snapshot without overwrite",MissingDestination);
        yield return("rc5 preexisting updater-name collisions are never overwritten or removed",NameConflicts);
        yield return("rc5 updater cannot target arbitrary names game folders SDK or recovery storage",Targets);
        yield return("rc5 actual Windows junction paths cannot bypass update directory locks",Junction);
        yield return("rc5 directory handles prevent renaming a checked installation path",DirectoryLock);
        yield return("rc5 helper waits for approval and exact parent exit before replacement",Sequencing);
        yield return("rc5 helper parent-exit timeout never applies or restarts",Timeout);
        yield return("rc5 mocked signed release metadata uses official asset URLs and rejects redirection",MetadataTransport);
        yield return("rc5 offline publisher tool produces verifier-compatible signature with test-only key",PublisherTool);
        yield return("rc5 safe readable release summary never loads HTML scripts or remote content",Notes);
        yield return("rc5 update indicator and disabled automatic install share live localized state",Ui);
        yield return("rc5 mocked startup and manual checks share cache and update global badge",StartupChecks);
        yield return("rc5 disabled automatic install gate refuses direct invocation without IO",UiFailClosed);
        yield return("rc5 six-language resources and existing application preferences remain intact",Localization);
