    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
    private static void Reject(Action action){try{action();}catch(Exception ex)when(ex is InvalidDataException or IOException or UnauthorizedAccessException or CryptographicException or OperationCanceledException){return;}throw new Exception("Expected self-update refusal.");}
    private static readonly Lazy<RSA> Key=new(()=>RSA.Create(3072));
    private static string Hash(byte[] bytes)=>Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant();
    private static string Temp(){var p=Path.Combine(Path.GetTempPath(),"RenoDX-RC5",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(p);return p;}
    private sealed class Fixture {
