        internal byte[] ZipBytes=[];
        internal SelfUpdateManifest Manifest=null!;internal SignedUpdateMetadata Signed=null!;internal ApplicationRelease Release=null!;
        internal readonly SelfUpdateVerifier Verifier=new(new Dictionary<string,string>{{"test-only",Convert.ToBase64String(Key.Value.ExportSubjectPublicKeyInfo())}});
        internal int Launches;
        internal Fixture(Action<ZipArchive>? extra=null) {
            Installation=Path.Combine(Root,"installation");Directory.CreateDirectory(Installation);Target=Path.Combine(Installation,SelfUpdateVerifier.Executable);File.WriteAllBytes(Target,Old);File.WriteAllText(Path.Combine(Installation,"user-settings.json"),"preserve all bytes");Directory.CreateDirectory(Path.Combine(Installation,"SDK"));File.WriteAllText(Path.Combine(Installation,"SDK","user.dll"),"user data; never loaded");
            using var memory=new MemoryStream();using(var zip=new ZipArchive(memory,ZipArchiveMode.Create,true)) {
                using(var member=zip.CreateEntry(SelfUpdateVerifier.Executable).Open())member.Write(New);
                using(var member=zip.CreateEntry("README.md").Open())member.Write(Encoding.UTF8.GetBytes("test notes"));
            }if(extra is not null){memory.Position=0;using var update=new ZipArchive(memory,ZipArchiveMode.Update,true);extra(update);}ZipBytes=memory.ToArray();Archive=Path.Combine(Root,"download.zip");File.WriteAllBytes(Archive,ZipBytes);
            Manifest=new(1,"test-only",ApplicationUpdateService.Repository,"stable","windows-x64",Next,"RenoDX_MFG_Unlocker_v1.3.0_Windows_x64.zip",ZipBytes.Length,Hash(ZipBytes),[new(SelfUpdateVerifier.Executable,New.Length,Hash(New)),new("README.md",10,Hash(Encoding.UTF8.GetBytes("test notes")))]);
