        }
        internal void Resign(SelfUpdateManifest manifest) {
            Manifest=manifest;var canonical=SelfUpdateVerifier.Canonical(manifest);Signed=new(canonical,Key.Value.SignData(canonical,HashAlgorithmName.SHA256,RSASignaturePadding.Pss));
            Release=new("v"+manifest.Version,"Synthetic signed fixture","# Notes\n- **Test**",DateTimeOffset.Parse("2026-11-02T00:00:00Z"),ApplicationUpdateService.WebRoot+"/releases/tag/v"+manifest.Version,manifest.FileName,ApplicationUpdateService.WebRoot+"/releases/download/v"+manifest.Version+"/"+manifest.FileName,manifest.Size,manifest.Sha256,new(manifest.FileName+".update.json",ApplicationUpdateService.WebRoot+"/releases/download/v"+manifest.Version+"/"+manifest.FileName+".update.json",Signed.Manifest.Length),new(manifest.FileName+".sig",ApplicationUpdateService.WebRoot+"/releases/download/v"+manifest.Version+"/"+manifest.FileName+".sig",Signed.Signature.Length));
        }
        internal PreparedSelfUpdate Prepare()=>SelfUpdateHandoff.Prepare(Verifier,Archive,Signed,Release,Current,Target,root:Path.Combine(Root,"staging"));
        internal SelfUpdateReplacement Engine(Action<string>? fault=null,Action<string,string>? launch=null)=>new(Verifier,p=>new("RenoDX MFG Unlocker",File.ReadAllBytes(p).SequenceEqual(New)?Next:Current,0x8664),launch??((target,_)=>{Check(File.ReadAllBytes(target).SequenceEqual(New),"Unverified launch");Launches++;}),fault);
        internal void Untouched()=>Check(File.ReadAllText(Path.Combine(Installation,"user-settings.json"))=="preserve all bytes"&&File.ReadAllText(Path.Combine(Installation,"SDK","user.dll"))=="user data; never loaded","User files changed");
