    private static void NoProductionTrust(){Check(SelfUpdateTrust.Configured&&SelfUpdateTrust.Keys.Count==1&&SelfUpdateTrust.Keys.ContainsKey("owner-release-2026"),"Approved production trust missing or polluted");var f=new Fixture();Reject(()=>new SelfUpdateVerifier().Verify(f.Signed,f.Release,Fixture.Current));Check(SelfUpdateHandoff.RunWorkerAsync(["--self-update-helper","invalid","1","0"]).GetAwaiter().GetResult()==78,"Unsigned helper mode entered");Reject(()=>SelfUpdateHandoff.StartAsync(f.Prepare()).GetAwaiter().GetResult());Check(f.Launches==0&&File.ReadAllBytes(f.Target).SequenceEqual(f.Old),"Production gate wrote or executed");}
    private static void Signature(){var f=new Fixture();var actual=f.Verifier.VerifyPackage(f.Archive,f.Signed,f.Release,Fixture.Current);Check(actual.Version==Fixture.Next&&actual.Files.Length==2,"Signed fixture not verified");Check(!SelfUpdateTrust.Keys.ContainsKey("test-only"),"Test trust leaked to production");}
    private static void BadSignatures(){var f=new Fixture();var bad=f.Signed.Signature.ToArray();bad[0]^=1;Reject(()=>f.Verifier.Verify(f.Signed with {Signature=bad},f.Release,Fixture.Current));using var wrong=RSA.Create(3072);var other=new SelfUpdateVerifier(new Dictionary<string,string>{{"test-only",Convert.ToBase64String(wrong.ExportSubjectPublicKeyInfo())}});Reject(()=>other.Verify(f.Signed,f.Release,Fixture.Current));var whitespace=f.Signed.Manifest.Concat(new byte[]{32}).ToArray();Reject(()=>f.Verifier.Verify(new(whitespace,Key.Value.SignData(whitespace,HashAlgorithmName.SHA256,RSASignaturePadding.Pss)),f.Release,Fixture.Current));var text=Encoding.UTF8.GetString(f.Signed.Manifest).Replace("\"Schema\":1,","\"Schema\":1,\"Schema\":1,");var duplicates=Encoding.UTF8.GetBytes(text);Reject(()=>f.Verifier.Verify(new(duplicates,Key.Value.SignData(duplicates,HashAlgorithmName.SHA256,RSASignaturePadding.Pss)),f.Release,Fixture.Current));}
    private static void VersionBindings(){foreach(var mutate in new Func<SelfUpdateManifest,SelfUpdateManifest>[] {m=>m with {Repository="attacker/repo"},m=>m with {Platform="windows-arm64"},m=>m with {Channel="preview"},m=>m with {Version="1.1.0"},m=>m with {Version="1.3.0-rc.1"},m=>m with {Schema=99}}){var f=new Fixture();f.Resign(mutate(f.Manifest));Reject(()=>f.Verifier.Verify(f.Signed,f.Release,Fixture.Current));}var good=new Fixture();Reject(()=>good.Verifier.Verify(good.Signed,good.Release,"1.3.0"));Check(good.Verifier.Verify(good.Signed,good.Release,"1.3.0-rc.1").Version=="1.3.0","Stable did not supersede same-version RC");}
    private static void HashBindings(){var f=new Fixture();foreach(var release in new[]{f.Release with {Size=f.Release.Size+1},f.Release with {Sha256=new string('0',64)},f.Release with {AssetName="Source code.zip"}})Reject(()=>f.Verifier.Verify(f.Signed,release,Fixture.Current));var bytes=File.ReadAllBytes(f.Archive);bytes[0]^=1;File.WriteAllBytes(f.Archive,bytes);Reject(()=>f.Verifier.VerifyPackage(f.Archive,f.Signed,f.Release,Fixture.Current));var g=new Fixture();g.Resign(g.Manifest with {Files=g.Manifest.Files.Select(file=>file.Path==SelfUpdateVerifier.Executable?file with {Sha256=new string('0',64)}:file).ToArray()});Reject(()=>g.Verifier.VerifyPackage(g.Archive,g.Signed,g.Release,Fixture.Current));}
    private static void UnsafeZip(){foreach(var path in new[]{"../escape.exe","/absolute.exe","C:/outside.exe","other.exe","sub/../../outside","LICENSES/../../../evil"}){var f=new Fixture(zip=>{using var file=zip.CreateEntry(path).Open();file.WriteByte(1);});Reject(()=>f.Prepare());Check(!Directory.Exists(Path.Combine(f.Root,"escape.exe"))&&File.ReadAllBytes(f.Target).SequenceEqual(f.Old),"Unsafe ZIP wrote target");}var g=new Fixture();g.Resign(g.Manifest with {Files=[new("../escape.exe",1,new string('0',64))]});Reject(()=>g.Verifier.Verify(g.Signed,g.Release,Fixture.Current));}
    private static void ArchiveLinks(){foreach(var attributes in new[]{unchecked((int)0xA1FF0000),0x400}){var f=new Fixture(zip=>{var e=zip.GetEntry("README.md")!;e.ExternalAttributes=attributes;});Reject(()=>f.Prepare());}var duplicate=new Fixture(zip=>zip.CreateEntry("readme.md"));Reject(()=>duplicate.Prepare());}
    private static void ZipLimits(){var f=new Fixture();f.Resign(f.Manifest with {Files=[new(SelfUpdateVerifier.Executable,513L*1024*1024,Hash(f.New))]});Reject(()=>f.Verifier.Verify(f.Signed,f.Release,Fixture.Current));var missing=new Fixture();missing.Resign(missing.Manifest with {Files=[..missing.Manifest.Files,new("CHANGELOG.md",0,Hash([]))]});Reject(()=>missing.Prepare());var corrupt=new Fixture();corrupt.ZipBytes=Encoding.UTF8.GetBytes("not a ZIP");File.WriteAllBytes(corrupt.Archive,corrupt.ZipBytes);corrupt.Resign(corrupt.Manifest with {Size=corrupt.ZipBytes.Length,Sha256=Hash(corrupt.ZipBytes)});Reject(()=>corrupt.Prepare());}
