    private static void RestartFailure(){var f=new Fixture();var result=f.Engine(launch:(_,_)=>throw new IOException("synthetic process creation denied")).Apply(f.Prepare());Check(result.Restored&&!result.Restarted&&File.ReadAllBytes(f.Target).SequenceEqual(f.Old),"Failed restart did not recover");f.Untouched();}
