    private static void ChangedFiles(){foreach(var name in new[]{"payload.exe","package.zip","target"}){var f=new Fixture();var update=f.Prepare();File.WriteAllText(name=="target"?f.Target:Path.Combine(update.Session,name),"changed after preparation");try{var result=f.Engine().Apply(update);Check(!result.Restarted&&result.Status!="Installed","Changed file installed");}catch(InvalidDataException){}Check(f.Launches==0,"Changed source executed");if(name!="target")Check(File.ReadAllBytes(f.Target).SequenceEqual(f.Old),"Changed source replaced target");}var g=new Fixture();var u=g.Prepare();var conflict=g.Engine(phase=>{if(phase=="AfterReplace"){var backup=Directory.GetFiles(g.Installation,"*.backup").Single();File.WriteAllText(backup,"tampered recovery");throw new IOException("failure with modified backup");}}).Apply(u);Check(conflict.Status=="Recovery required"&&!conflict.Restarted&&!conflict.Restored&&g.Launches==0,"Tampered recovery restored or launched");}
