    private static void Notes(){var text=UpdateNotesSummary.Readable("# Heading\n- **Important** `key`\n[Source](https://github.com/ExiZz1/RenoDX-MFG-Unlocker)\n![Remote](https://evil.invalid/image)\n<script>alert('inert')</script>");Check(text.StartsWith("Heading")&&text.Contains("• Important key")&&!text.Contains("**")&&!text.Contains("<script>")&&!text.Contains("!["),"Unreadable/raw Markdown");Check(UpdateNotesSummary.Readable(new string('a',50000)).Length<25000,"Summary unbounded");}
    private static void Pump(Task task){var until=Stopwatch.StartNew();while(!task.IsCompleted&&until.Elapsed<TimeSpan.FromSeconds(8)){Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.Background);Thread.Sleep(1);}Check(task.IsCompleted,"Unshown WPF operation timed out");task.GetAwaiter().GetResult();}
    private static void Ui()=>WpfCheckHost.Run(()=>{var f=new Fixture();var callbacks=0;using var http=new HttpClient(new MockHandler(_=>new(HttpStatusCode.OK){Content=new StringContent(Metadata(f))}));using var service=new ApplicationUpdateService(http);using var view=new ApplicationUpdateView(service,Fixture.Current,Path.Combine(f.Root,"downloads"),_=>callbacks++,_=>callbacks++);var events=0;view.CheckCompleted+=_=>events++;Pump(view.CheckAsync());Check(events==1&&!view.InstallButton.IsEnabled&&view.DownloadButton.IsEnabled&&view.Notes.Text.Contains("• Test")&&callbacks==0,"UI enabled unsigned replacement or failed notes");var l=LocalizedPresentation.Language;foreach(var state in Enum.GetValues<UpdateIndicatorState>()){var p=UpdateIndicatorPresentation.Describe(state,Fixture.Next,l);Check(p.Notify==(state==UpdateIndicatorState.Available)&&p.Tooltip.Length>0,"Badge state incorrect");}var window=new MainWindow();try{var badge=(Button)window.FindName("ApplicationUpdateBadge");Check(badge is not null&&((FrameworkElement)badge.Parent).Parent is not null,"Global version badge missing");Check(((System.Windows.Shapes.Ellipse)window.FindName("ApplicationUpdateBadgeDot")).Visibility==Visibility.Collapsed,"Neutral indicator misleading");}finally{window.Close();}});
    private static void StartupChecks()=>WpfCheckHost.Run(()=>{var f=new Fixture();var requests=0;var offline=false;using var http=new HttpClient(new MockHandler(_=>{requests++;if(offline)throw new HttpRequestException("synthetic offline");return new(HttpStatusCode.OK){Content=new StringContent(Metadata(f))};}));using var service=new ApplicationUpdateService(http);var window=new MainWindow();const System.Reflection.BindingFlags flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;try{typeof(MainWindow).GetField("applicationUpdates",flags)!.SetValue(window,service);Pump((Task)typeof(MainWindow).GetMethod("CheckApplicationUpdatesAtLaunchAsync",flags)!.Invoke(window,null)!);Check(requests==1&&((System.Windows.Shapes.Ellipse)window.FindName("ApplicationUpdateBadgeDot")).Visibility==Visibility.Visible,"Startup result not reflected globally");using var view=new ApplicationUpdateView(service,Fixture.Current,Path.Combine(f.Root,"downloads"),_=>{},_=>{});Pump(view.CheckAsync());Check(requests==1,"Dialog opening refetched cached startup metadata");Pump(view.CheckAsync(true));Check(requests==2,"Explicit manual refresh did not fetch");offline=true;Pump(view.CheckAsync(true));Check(!view.DownloadButton.IsEnabled&&!view.InstallButton.IsEnabled,"Offline check left unsafe controls enabled");}finally{window.Close();}});
    private static void UiFailClosed()=>WpfCheckHost.Run(()=>{var f=new Fixture();var calls=0;using var http=new HttpClient(new MockHandler(_=>{calls++;return new(HttpStatusCode.OK){Content=new StringContent(Metadata(f))};}));using var service=new ApplicationUpdateService(http);using var view=new ApplicationUpdateView(service,Fixture.Current,Path.Combine(f.Root,"downloads"),_=>{},_=>{},signingReady:()=>false,install:(_,_,_,_,_)=>throw new Exception("Disabled install callback entered"));Pump(view.CheckAsync());var before=calls;Pump(view.DownloadAndInstallAsync());view.InstallButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(calls==before&&!Directory.Exists(Path.Combine(f.Root,"downloads")),"Untrusted direct UI invocation did network/file work");});
    private static void Localization()=>WpfCheckHost.Run(()=>{var language=LocalizedPresentation.Language;try{Check(language.ValidateCatalogs().Count==0,"Catalog mismatch");foreach(var culture in UiLocalization.Cultures){language.SetCulture(culture,false);foreach(var key in new[]{SelfUpdateTrust.MissingKey,"Download and Install","Replace application and restart?","Application update available: {0}","Verifying signed package…","Update check unavailable. Click to retry."})Check(language.GetCatalog(culture).ContainsKey(key)&&(culture=="en-US"||language.Lookup(key)!=key),"Missing RC5 translation "+culture+" / "+key);Check(UpdateIndicatorPresentation.Describe(UpdateIndicatorState.Available,"1.3.0",language).Tooltip.Contains("1.3.0"),"Culture changed version");}var path=Path.Combine(Temp(),"preferences.json");var preferences=new ApplicationPreferences(path);Check(!preferences.CheckUpdatesAtLaunch,"Forced startup checks");preferences.SetUpdateCheck(true);Check(new ApplicationPreferences(path).CheckUpdatesAtLaunch,"Preference lost");preferences.SetUpdateCheck(false);Check(!new ApplicationPreferences(path).CheckUpdatesAtLaunch,"Disable ignored");}finally{language.SetCulture("en-US",false);}});
